const input = $input.first().json;
const body = input.body || input;

// Extract CV file metadata from binary or form data
const cvFile = body.data?.cv_file || body.cv_file || {};
const fileName = cvFile.fileName || cvFile.name || "cv-uploaded";
const mimeType = cvFile.mimeType || cvFile.type || "application/pdf";

// Extract text — in production, wire this to a PDF parser (e.g. CloudConvert, DocParser)
// If your form sends pre-extracted text, use it. Otherwise flag for review.
let extractedText = body.cv_text || body.data?.cv_text || "";
let extractionConfidence = "High";

if (!extractedText || extractedText.trim().length < 100) {
    extractionConfidence = "Low";
    extractedText = "[EXTRACTION PENDING — Scanned PDF or image detected. Manual review required.]";
}

// Normalise email for duplicate matching
const normalizedEmail = (body.email || "").toLowerCase().trim().replace(/\s+/g, "");

// Build the candidate record
