    candidate_name: body.candidate_name || body.name || "",
    email: body.email || "",
    normalized_email: normalizedEmail,
    phone: body.phone || "",
    job_id: body.job_id || body.job_reference || "",
    role_applied_for: body.role_applied_for || body.role || "",
    years_of_experience: body.years_of_experience || null,
