// ============================================
// PARSE STRUCTURED AI OUTPUT
// ============================================
const aiResponse = $input.first().json;
const candidate = $input.first().json; // full candidate data is passed through

let parsed;
try {
    const content = aiResponse.content || aiResponse.message?.content || aiResponse.choices?.[0]?.message?.content || "{}";
    // Extract JSON block if wrapped in markdown
    const jsonMatch = content.match(/\{[\s\S]*?\}/);
    parsed = JSON.parse(jsonMatch ? jsonMatch[0] : content);
} catch (e) {
    parsed = {
        requirement_match_score: null,
        constraint_pass_fail: "FAIL",
        constraint_reason: "AI response could not be parsed — manual review required",
        score_evidence: "Parse error: " + String(e.message).substring(0, 200)
    };
}

// Validate and clamp score
let score = parsed.requirement_match_score;
if (typeof score !== "number" || isNaN(score)) score = null;
else if (score < 0) score = 0;
else if (score > 100) score = 100;

// Normalise constraint
let constraint = (parsed.constraint_pass_fail || "").toUpperCase();
if (constraint !== "PASS" && constraint !== "FAIL") constraint = "FAIL";

const result = {
    candidate_name: candidate.candidate_name,
    email: candidate.email,
    normalized_email: candidate.normalized_email,
    phone: candidate.phone,
    job_id: candidate.job_id,
    role_applied_for: candidate.role_applied_for,
    years_of_experience: candidate.years_of_experience,
    cv_file_link: candidate.cv_file_link,
    linkedin_url: candidate.linkedin_url,
    github_url: candidate.github_url,
    date_applied: candidate.date_applied,
    requirement_match_score: score,
    constraint_pass_fail: constraint,
    constraint_reason: (parsed.constraint_reason || "").substring(0, 120),
    score_evidence: (parsed.score_evidence || "").substring(0, 300),
    extraction_confidence: candidate.extraction_confidence,
    screening_status: "Screened",
    status: candidate.status,
    duplicate_flag: candidate.duplicate_flag,
    raw_extracted_summary: candidate.raw_extracted_summary,
    last_updated_timestamp: $now.toISO()
};

return [{ json: result }];

// ============================================
// ERROR HANDLING — Extraction Failed Branch
// ============================================
const input = $input.first().json;

const errorRecord = {
    candidate_name: input.candidate_name || "Unknown",
    email: input.email || "",
    phone: input.phone || "",
    job_id: input.job_id || "",
    role_applied_for: input.role_applied_for || "",
    date_applied: $now.toISO(),
    screening_status: "Extraction Failed",
    status: "New",
    score_evidence: "CV text could not be extracted. Likely causes: scanned image PDF, corrupted file, or unsupported format.",
    last_updated_timestamp: $now.toISO()
};

return [{ json: errorRecord }];
